const listOpenAlerts = `-- name: ListOpenAlerts :many
SELECT id, device_id, kind, details, created_at, resolved_at, resolved_by FROM device_alerts
WHERE device_id = ANY($1::uuid[]) AND resolved_at IS NULL
ORDER BY created_at, id
`

// The unresolved alerts of each of device_ids, oldest first.
func (q *Queries) ListOpenAlerts(ctx context.Context, deviceIds []uuid.UUID) ([]DeviceAlert, error) {
	rows, err := q.db.Query(ctx, listOpenAlerts, deviceIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DeviceAlert
	for rows.Next() {
		var i DeviceAlert
		if err := rows.Scan(
			&i.ID,
			&i.DeviceID,
			&i.Kind,
			&i.Details,
			&i.CreatedAt,
			&i.ResolvedAt,
			&i.ResolvedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockDeviceEnrollment = `-- name: LockDeviceEnrollment :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::uuid::text, 0))
`

func (q *Queries) LockDeviceEnrollment(ctx context.Context, serverID uuid.UUID) error {
	_, err := q.db.Exec(ctx, lockDeviceEnrollment, serverID)
	return err
}

const openUUIDMismatchAlert = `-- name: OpenUUIDMismatchAlert :one
INSERT INTO device_alerts (device_id, kind, details)
VALUES ($1, 'uuid_mismatch', $2)
ON CONFLICT (device_id, kind) WHERE resolved_at IS NULL DO NOTHING
RETURNING id
`

type OpenUUIDMismatchAlertParams struct {
	DeviceID uuid.UUID
	Details  []byte
}

// Returns no row when the device already has an open uuid_mismatch alert.
func (q *Queries) OpenUUIDMismatchAlert(ctx context.Context, arg OpenUUIDMismatchAlertParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, openUUIDMismatchAlert, arg.DeviceID, arg.Details)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

