const storeDeviceSysinfo = `-- name: StoreDeviceSysinfo :execrows
UPDATE devices
SET hostname = $1, os = $2, cpu = $3,
    memory = $4, client_version = $5,
    username = $6, presets = $7, updated_at = now()
WHERE id = $8 AND uuid = $9 AND state IN ('pending', 'approved')
`

type StoreDeviceSysinfoParams struct {
	Hostname      string
	OS            string
	CPU           string
	Memory        string
	ClientVersion string
	Username      string
	Presets       []byte
	ID            uuid.UUID
	UUID          string
}

// Matches only while the device still has this uuid and is pending or
// approved, so a concurrent reject, archive or re-pin wins.
func (q *Queries) StoreDeviceSysinfo(ctx context.Context, arg StoreDeviceSysinfoParams) (int64, error) {
	result, err := q.db.Exec(ctx, storeDeviceSysinfo,
		arg.Hostname,
		arg.OS,
		arg.CPU,
		arg.Memory,
		arg.ClientVersion,
		arg.Username,
		arg.Presets,
		arg.ID,
		arg.UUID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

