const updateLastSeen = `-- name: UpdateLastSeen :exec
UPDATE devices AS d
SET last_seen_at = v.seen_at
FROM (
    SELECT unnest($2::text[]) AS rustdesk_id,
           unnest($3::timestamptz[]) AS seen_at
) AS v
WHERE d.server_id = $1
  AND d.rustdesk_id = v.rustdesk_id
  AND d.state IN ('pending', 'approved')
`

type UpdateLastSeenParams struct {
	ServerID    uuid.UUID
	RustdeskIds []string
	SeenAts     []time.Time
}

// Batch-writes heartbeat times from the online tracker. Only pending and
// approved devices are touched: a heartbeat can race an admin reject or
// archive, and the reject must not be followed by a fresh last_seen_at.
func (q *Queries) UpdateLastSeen(ctx context.Context, arg UpdateLastSeenParams) error {
	_, err := q.db.Exec(ctx, updateLastSeen, arg.ServerID, arg.RustdeskIds, arg.SeenAts)
	return err
}
